    [33] = {
      beijing = 9013,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      ruchang = 0,
      sentence = "Before coming, I'd saved a blueprint layout of the whole hospital. The most suspicious thing about it was an unreasonably large archive room on the top floor.",
