    [10] = {
      beijing = 1392,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "With not many opportunities to get together with colleagues, everyone took the chance to mingle and chat. Not far away, Kiro was engrossed in conversation with a director, not noticing me in the slightest.",
