    },
    [11] = {
      beijing = 1392,
      dialog = 3,
      music = "19_Daily02",
      renwu = "npc",
      sentence = "A wave of disappointment crested in my heart. Just then, a director that I'd worked with before, Mr. Sun, came walking over with a glass raised in a toast.",
